from sklearn.compose import ColumnTransformer
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler, OneHotEncoder, PowerTransformer
from sklearn.impute import SimpleImputer
from sklearn.svm import SVC

def build_pipeline_e007(profile: dict):
    columns = profile['columns']
    numeric = [c['name'] for c in columns if c['kind'] == 'numeric']
    categorical = [c['name'] for c in columns if c['kind'] in ('categorical', 'boolean')]
    transformers = []
    if numeric:
        num_pipe = Pipeline([('impute', SimpleImputer(strategy='median')), ('power', PowerTransformer(method='yeo-johnson')), ('scale', StandardScaler())])
        transformers.append(('num', num_pipe, numeric))
    if categorical:
        cat_pipe = Pipeline([('impute', SimpleImputer(strategy='most_frequent')), ('onehot', OneHotEncoder(handle_unknown='ignore', sparse_output=False, max_categories=30))])
        transformers.append(('cat', cat_pipe, categorical))
    preprocess = ColumnTransformer(transformers, remainder='drop')
    if profile['problem_type'] == 'regression':
        from sklearn.svm import SVR
        model = SVR()
    else:
        model = SVC(probability=True, random_state=0)
    return Pipeline([('preprocess', preprocess), ('model', model)])


