from sklearn.compose import ColumnTransformer
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler, OneHotEncoder
from sklearn.impute import SimpleImputer
from sklearn.neural_network import MLPClassifier, MLPRegressor

def build_pipeline_e006(profile: dict):
    columns = profile['columns']
    numeric = [c['name'] for c in columns if c['kind'] == 'numeric']
    categorical = [c['name'] for c in columns if c['kind'] in ('categorical', 'boolean')]
    transformers = []
    if numeric:
        num_pipe = Pipeline([('impute', SimpleImputer(strategy='median')), ('scale', StandardScaler())])
        transformers.append(('num', num_pipe, numeric))
    if categorical:
        cat_pipe = Pipeline([('impute', SimpleImputer(strategy='most_frequent')), ('onehot', OneHotEncoder(handle_unknown='ignore', sparse_output=False, max_categories=30))])
        transformers.append(('cat', cat_pipe, categorical))
    preprocess = ColumnTransformer(transformers, remainder='drop')
    if profile['problem_type'] == 'regression':
        model = MLPRegressor(hidden_layer_sizes=(100, 50), max_iter=500, random_state=42)
    else:
        model = MLPClassifier(hidden_layer_sizes=(100, 50), max_iter=500, random_state=42)
    return Pipeline([('preprocess', preprocess), ('model', model)])


def build_pipeline(profile):
    members = [
        ("e007", build_pipeline_e007(profile)),
        ("e006", build_pipeline_e006(profile)),
    ]
    weights = None
    if profile["problem_type"] == "regression":
        return VotingRegressor(members, weights=weights)
    return VotingClassifier(members, voting="soft", weights=weights)
